const keys=new WeakMap();
export function rayGeometryKey(geometry){const position=geometry.attributes.position,index=geometry.index,key=[position,position.data?.version??position.version,index,index?.version],old=keys.get(geometry);if(old&&key.every((v,i)=>v===old.key[i]))return old.value;let hash=2166136261;for(const attribute of [position,index])if(attribute){const a=attribute.data?.array??attribute.array,bytes=new Uint8Array(a.buffer,a.byteOffset,a.byteLength);for(const byte of bytes)hash=Math.imul(hash^byte,16777619)>>>0;}const value='static:'+position.count+':'+(index?.count||0)+':'+hash.toString(16);keys.set(geometry,{key,value});return value;}
